import type { SessionMessage } from "claude-code";

/** A check command: `just check`, `just test F`, `just lab`, `just lint`, `just validate`, or `bun test F`, with no shell operator. */
const CHECK =
  /^(?:just (?:check|test|lab|lint|validate)|bun test)(?: [^;&|<>$`\n]*)?$/;

/** The check commands whose last run passed, in the order of their first run. */
export const passedChecks = (messages: readonly SessionMessage[]): string[] => {
  const outcome = new Map<string, boolean>();
  for (const use of messages.flatMap((m) => m.toolUses)) {
    const command = (use.input as { command?: unknown } | undefined)?.command;
    if (use.tool !== "Bash" || typeof command !== "string") continue;
    const trimmed = command.trim();
    if (!CHECK.test(trimmed) || use.text === undefined) continue;
    outcome.set(trimmed, use.isError !== true);
  }
  return [...outcome].filter(([, isPassed]) => isPassed).map(([c]) => c);
};
